+import { describe, it, expect } from 'vitest';
+
+import {
+  BASE_MODEL_FLUX1_DEV,
+  BASE_MODEL_NANO_BANANA,
+  BASE_MODEL_NANO_BANANA_PRO,
+  BASE_MODEL_GPT_IMAGE,
+  isGptModel,
+  isGeminiModel,
+  isGemini25Plus,
+  isFlux1,
+  isFlux2
+} from '@/constants/image';
+
+describe('Image model detection functions', () => {
+  describe('isFlux2', () => {
+    it('should return true for flux2 models', () => {
+      expect(isFlux2('flux2.safetensors')).toBe(true);
+      expect(isFlux2('flux2-dev.safetensors')).toBe(true);
+      expect(isFlux2('flux2-schnell.safetensors')).toBe(true);
+    });
+
+    it('should return false for flux1 models', () => {
+      expect(isFlux2('flux1-dev.safetensors')).toBe(false);
+      expect(isFlux2(BASE_MODEL_FLUX1_DEV)).toBe(false);
+    });
+
+    it('should return false for non-flux models', () => {
+      expect(isFlux2(BASE_MODEL_NANO_BANANA)).toBe(false);
+      expect(isFlux2(BASE_MODEL_GPT_IMAGE)).toBe(false);
+      expect(isFlux2('sd15.safetensors')).toBe(false);
+    });
+  });
+
+  describe('isFlux1', () => {
+    it('should return true for flux1 models', () => {
+      expect(isFlux1('flux1-dev.safetensors')).toBe(true);
+      expect(isFlux1(BASE_MODEL_FLUX1_DEV)).toBe(true);
+      expect(isFlux1('flux1-schnell.safetensors')).toBe(true);
+    });
+
+    it('should return false for flux2 models', () => {
+      expect(isFlux1('flux2.safetensors')).toBe(false);
+      expect(isFlux1('flux2-dev.safetensors')).toBe(false);
+    });
+
+    it('should return false for non-flux models', () => {
+      expect(isFlux1(BASE_MODEL_NANO_BANANA)).toBe(false);
+      expect(isFlux1(BASE_MODEL_GPT_IMAGE)).toBe(false);
+    });
+  });
+
+  describe('isGptModel', () => {
+    it('should return true for GPT models', () => {
+      expect(isGptModel(BASE_MODEL_GPT_IMAGE)).toBe(true);
+      expect(isGptModel('gpt-image-2.0')).toBe(true);
+      expect(isGptModel('gpt-4-vision')).toBe(true);
+    });
+
+    it('should return false for non-GPT models', () => {
+      expect(isGptModel(BASE_MODEL_NANO_BANANA)).toBe(false);
+      expect(isGptModel(BASE_MODEL_FLUX1_DEV)).toBe(false);
+      expect(isGptModel('flux2.safetensors')).toBe(false);
+    });
+  });
+
+  describe('isGeminiModel', () => {
+    it('should return true for Gemini models', () => {
+      expect(isGeminiModel(BASE_MODEL_NANO_BANANA)).toBe(true);
+      expect(isGeminiModel(BASE_MODEL_NANO_BANANA_PRO)).toBe(true);
+      expect(isGeminiModel('gemini-2.0-flash')).toBe(true);
+    });
+
+    it('should return false for non-Gemini models', () => {
+      expect(isGeminiModel(BASE_MODEL_GPT_IMAGE)).toBe(false);
+      expect(isGeminiModel(BASE_MODEL_FLUX1_DEV)).toBe(false);
+      expect(isGeminiModel('flux2.safetensors')).toBe(false);
+    });
+  });
+
+  describe('isGemini25Plus', () => {
+    it('should return true for Gemini 2.5+ models', () => {
+      expect(isGemini25Plus('gemini-2.5-flash-image')).toBe(true);
+      expect(isGemini25Plus('gemini-3-pro-image-preview')).toBe(true);
+      expect(isGemini25Plus('gemini-2.5-pro')).toBe(true);
+      expect(isGemini25Plus('gemini-3.0-ultra')).toBe(true);
+    });
+
+    it('should return false for Gemini models below 2.5', () => {
+      expect(isGemini25Plus('gemini-2.0-flash')).toBe(false);
+      expect(isGemini25Plus('gemini-1.5-pro')).toBe(false);
+      expect(isGemini25Plus('gemini-1.0-pro')).toBe(false);
+    });
+
+    it('should return false for non-Gemini models', () => {
+      expect(isGemini25Plus(BASE_MODEL_GPT_IMAGE)).toBe(false);
+      expect(isGemini25Plus(BASE_MODEL_FLUX1_DEV)).toBe(false);
+      expect(isGemini25Plus('flux2.safetensors')).toBe(false);
+    });
+  });
+});
