+import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';
+
+import { getImageUrlFromId } from '@/utils/image';
+
+describe('getImageUrlFromId', () => {
+  const originalFetch = global.fetch;
+
+  beforeEach(() => {
+    vi.clearAllMocks();
+  });
+
+  afterEach(() => {
+    global.fetch = originalFetch;
+  });
+
+  describe('URL passthrough', () => {
+    it('should return HTTP URLs as-is', async () => {
+      const httpUrl = 'http://example.com/image.png';
+      const result = await getImageUrlFromId(httpUrl);
+      expect(result).toBe(httpUrl);
+    });
+
+    it('should return HTTPS URLs as-is', async () => {
+      const httpsUrl = 'https://example.com/image.png';
+      const result = await getImageUrlFromId(httpsUrl);
+      expect(result).toBe(httpsUrl);
+    });
+
+    it('should return data URIs as-is', async () => {
+      const dataUri = 'data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNk+M9QDwADhgGAWjR9awAAAABJRU5ErkJggg==';
+      const result = await getImageUrlFromId(dataUri);
+      expect(result).toBe(dataUri);
+    });
+  });
+
+  describe('API fetch for image IDs', () => {
+    it('should fetch URL from API for valid image ID', async () => {
+      const mockUrl = 'https://cdn.example.com/images/abc123.png';
+      global.fetch = vi.fn().mockResolvedValue({
+        ok: true,
+        json: () => Promise.resolve([mockUrl])
+      });
+
+      const result = await getImageUrlFromId('abc123');
+
+      expect(global.fetch).toHaveBeenCalledWith(
+        '/api/images/src?ids=abc123&format=url'
+      );
+      expect(result).toBe(mockUrl);
+    });
+
+    it('should return null when API returns empty array', async () => {
+      global.fetch = vi.fn().mockResolvedValue({
+        ok: true,
+        json: () => Promise.resolve([])
+      });
+
+      const result = await getImageUrlFromId('nonexistent-id');
+
+      expect(result).toBeNull();
+    });
+
+    it('should return null when API response is not ok', async () => {
+      global.fetch = vi.fn().mockResolvedValue({
+        ok: false,
+        status: 404
+      });
+
+      const result = await getImageUrlFromId('invalid-id');
+
+      expect(result).toBeNull();
+    });
+
+    it('should return null when fetch throws an error', async () => {
+      global.fetch = vi.fn().mockRejectedValue(new Error('Network error'));
+
+      const result = await getImageUrlFromId('abc123');
+
+      expect(result).toBeNull();
+    });
+
+    it('should return null when API returns non-array response', async () => {
+      global.fetch = vi.fn().mockResolvedValue({
+        ok: true,
+        json: () => Promise.resolve({ url: 'something' })
+      });
+
+      const result = await getImageUrlFromId('abc123');
+
+      expect(result).toBeNull();
+    });
+  });
+});

