@@ -0,0 +1,304 @@
+import { describe, it, expect, vi, beforeEach } from 'vitest';
+
+import {
+  BASE_MODEL_FLUX1_DEV,
+  BASE_MODEL_NANO_BANANA,
+  isFlux2
+} from '@/constants/image';
+
+/**
+ * Test suite for reference image selection logic.
+ *
+ * These tests verify the business logic for reference image selection
+ * without testing UI components. The logic includes:
+ * - Maximum image limits per model
+ * - Duplicate image detection
+ * - Model-specific constraints (FLUX2 doesn't support img2img)
+ */
+
+// Mock the ReferenceImageData interface from the component
+interface ReferenceImageData {
+  imageId: string;
+  url: string;
+}
+
+// Pure functions extracted from FloatingTextareaContainer logic for testing
+const MAX_REFERENCE_IMAGES_DEFAULT = 4;
+const MAX_REFERENCE_IMAGES_FLUX1_DEV = 1;
+
+function getMaxReferenceImages(baseModel: string): number {
+  return baseModel === BASE_MODEL_FLUX1_DEV
+    ? MAX_REFERENCE_IMAGES_FLUX1_DEV
+    : MAX_REFERENCE_IMAGES_DEFAULT;
+}
+
+function shouldShowReferenceImageButton(baseModel: string): boolean {
+  return !isFlux2(baseModel);
+}
+
+function isImageAlreadySelected(
+  referenceImages: ReferenceImageData[],
+  imageId: string
+): boolean {
+  return referenceImages.some((img) => img.imageId === imageId);
+}
+
+function canAddMoreImages(
+  referenceImages: ReferenceImageData[],
+  maxReferenceImages: number
+): boolean {
+  return referenceImages.length < maxReferenceImages;
+}
+
+function addReferenceImage(
+  referenceImages: ReferenceImageData[],
+  imageId: string,
+  url: string,
+  maxReferenceImages: number
+): { images: ReferenceImageData[]; error: string | null } {
+  // Check duplicate
+  if (isImageAlreadySelected(referenceImages, imageId)) {
+    return { images: referenceImages, error: 'imageAlreadySelected' };
+  }
+
+  // Check limit
+  if (!canAddMoreImages(referenceImages, maxReferenceImages)) {
+    return { images: referenceImages, error: 'maxImagesReached' };
+  }
+
+  // Add image
+  return {
+    images: [...referenceImages, { imageId, url }],
+    error: null
+  };
+}
+
+function removeReferenceImage(
+  referenceImages: ReferenceImageData[],
+  imageId: string
+): ReferenceImageData[] {
+  return referenceImages.filter((img) => img.imageId !== imageId);
+}
+
+function adjustImagesForModelChange(
+  referenceImages: ReferenceImageData[],
+  newBaseModel: string
+): { images: ReferenceImageData[]; wasAdjusted: boolean } {
+  // FLUX2 doesn't support img2img at all
+  if (isFlux2(newBaseModel)) {
+    return { images: [], wasAdjusted: referenceImages.length > 0 };
+  }
+
+  // FLUX1_DEV limits to 1 reference image
+  if (
+    newBaseModel === BASE_MODEL_FLUX1_DEV &&
+    referenceImages.length > MAX_REFERENCE_IMAGES_FLUX1_DEV
+  ) {
+    return {
+      images: referenceImages.slice(0, MAX_REFERENCE_IMAGES_FLUX1_DEV),
+      wasAdjusted: true
+    };
+  }
+
+  return { images: referenceImages, wasAdjusted: false };
+}
+
+describe('Reference Image Selection Logic', () => {
+  describe('getMaxReferenceImages', () => {
+    it('should return 1 for FLUX1_DEV model', () => {
+      expect(getMaxReferenceImages(BASE_MODEL_FLUX1_DEV)).toBe(1);
+    });
+
+    it('should return 4 for other models', () => {
+      expect(getMaxReferenceImages(BASE_MODEL_NANO_BANANA)).toBe(4);
+      expect(getMaxReferenceImages('flux2.safetensors')).toBe(4);
+      expect(getMaxReferenceImages('sd15.safetensors')).toBe(4);
+    });
+  });
+
+  describe('shouldShowReferenceImageButton', () => {
+    it('should return false for FLUX2 models (no img2img support)', () => {
+      expect(shouldShowReferenceImageButton('flux2.safetensors')).toBe(false);
+      expect(shouldShowReferenceImageButton('flux2-dev.safetensors')).toBe(
+        false
+      );
+    });
+
+    it('should return true for other models', () => {
+      expect(shouldShowReferenceImageButton(BASE_MODEL_FLUX1_DEV)).toBe(true);
+      expect(shouldShowReferenceImageButton(BASE_MODEL_NANO_BANANA)).toBe(true);
+      expect(shouldShowReferenceImageButton('sd15.safetensors')).toBe(true);
+    });
+  });
+
+  describe('isImageAlreadySelected', () => {
+    const existingImages: ReferenceImageData[] = [
+      { imageId: 'img-1', url: 'https://example.com/1.png' },
+      { imageId: 'img-2', url: 'https://example.com/2.png' }
+    ];
+
+    it('should return true for already selected images', () => {
+      expect(isImageAlreadySelected(existingImages, 'img-1')).toBe(true);
+      expect(isImageAlreadySelected(existingImages, 'img-2')).toBe(true);
+    });
+
+    it('should return false for new images', () => {
+      expect(isImageAlreadySelected(existingImages, 'img-3')).toBe(false);
+      expect(isImageAlreadySelected(existingImages, 'new-image')).toBe(false);
+    });
+
+    it('should return false for empty array', () => {
+      expect(isImageAlreadySelected([], 'img-1')).toBe(false);
+    });
+  });
+
+  describe('canAddMoreImages', () => {
+    it('should return true when below limit', () => {
+      const images: ReferenceImageData[] = [
+        { imageId: 'img-1', url: 'url1' }
+      ];
+      expect(canAddMoreImages(images, 4)).toBe(true);
+    });
+
+    it('should return false when at limit', () => {
+      const images: ReferenceImageData[] = [
+        { imageId: 'img-1', url: 'url1' },
+        { imageId: 'img-2', url: 'url2' },
+        { imageId: 'img-3', url: 'url3' },
+        { imageId: 'img-4', url: 'url4' }
+      ];
+      expect(canAddMoreImages(images, 4)).toBe(false);
+    });
+
+    it('should respect FLUX1_DEV limit of 1', () => {
+      const noImages: ReferenceImageData[] = [];
+      const oneImage: ReferenceImageData[] = [{ imageId: 'img-1', url: 'url1' }];
+
+      expect(canAddMoreImages(noImages, 1)).toBe(true);
+      expect(canAddMoreImages(oneImage, 1)).toBe(false);
+    });
+  });
+
+  describe('addReferenceImage', () => {
+    it('should add image when valid', () => {
+      const result = addReferenceImage([], 'new-img', 'https://url.com', 4);
+
+      expect(result.error).toBeNull();
+      expect(result.images).toHaveLength(1);
+      expect(result.images[0]).toEqual({
+        imageId: 'new-img',
+        url: 'https://url.com'
+      });
+    });
+
+    it('should return error for duplicate image', () => {
+      const existing: ReferenceImageData[] = [
+        { imageId: 'img-1', url: 'url1' }
+      ];
+      const result = addReferenceImage(existing, 'img-1', 'url1', 4);
+
+      expect(result.error).toBe('imageAlreadySelected');
+      expect(result.images).toBe(existing); // Original array unchanged
+    });
+
+    it('should return error when at max limit', () => {
+      const full: ReferenceImageData[] = [
+        { imageId: 'img-1', url: 'url1' },
+        { imageId: 'img-2', url: 'url2' },
+        { imageId: 'img-3', url: 'url3' },
+        { imageId: 'img-4', url: 'url4' }
+      ];
+      const result = addReferenceImage(full, 'img-5', 'url5', 4);
+
+      expect(result.error).toBe('maxImagesReached');
+      expect(result.images).toBe(full);
+    });
+
+    it('should respect FLUX1_DEV limit of 1', () => {
+      const oneImage: ReferenceImageData[] = [{ imageId: 'img-1', url: 'url1' }];
+      const result = addReferenceImage(oneImage, 'img-2', 'url2', 1);
+
+      expect(result.error).toBe('maxImagesReached');
+    });
+  });
+
+  describe('removeReferenceImage', () => {
+    const images: ReferenceImageData[] = [
+      { imageId: 'img-1', url: 'url1' },
+      { imageId: 'img-2', url: 'url2' },
+      { imageId: 'img-3', url: 'url3' }
+    ];
+
+    it('should remove specified image', () => {
+      const result = removeReferenceImage(images, 'img-2');
+
+      expect(result).toHaveLength(2);
+      expect(result.find((img) => img.imageId === 'img-2')).toBeUndefined();
+      expect(result.find((img) => img.imageId === 'img-1')).toBeDefined();
+      expect(result.find((img) => img.imageId === 'img-3')).toBeDefined();
+    });
+
+    it('should return original array if image not found', () => {
+      const result = removeReferenceImage(images, 'nonexistent');
+
